const incoming = $input.first().json;
const payment = incoming.body ?? incoming;

const invoiceId = String(payment.invoiceId ?? '').trim();
const paymentId = String(payment.paymentId ?? '').trim();
const expectedAmount = Number(payment.expectedAmount);
const paidAmount = Number(payment.paidAmount);
const currency = String(payment.currency ?? 'USD').trim().toUpperCase();

if (!invoiceId || !paymentId || !Number.isFinite(expectedAmount) || !Number.isFinite(paidAmount) || expectedAmount < 0 || paidAmount < 0) {
  return [{ json: {
    success: false,
    workflow: 'Invoice & Payment Monitoring',
    status: 'INVALID_DATA',
    message: 'Provide invoiceId, paymentId, expectedAmount and paidAmount as valid values.'
  }}];
}

const amountMatches = Math.abs(expectedAmount - paidAmount) < 0.01;
const status = paidAmount === 0
  ? 'UNPAID'
  : amountMatches
    ? 'PAID'
    : paidAmount < expectedAmount
      ? 'PARTIALLY_PAID'
      : 'OVERPAID';

const riskFlags = [];
if (payment.duplicate === true) riskFlags.push('Payment marked as duplicate by upstream system');
if (!amountMatches && paidAmount > 0) riskFlags.push('Paid amount does not match invoice total');
if (payment.referenceVerified === false) riskFlags.push('Payment reference could not be verified');

return [{ json: {
  success: true,
  workflow: 'Invoice & Payment Monitoring',
  reconciliation: {
    invoiceId, paymentId, currency,
    expectedAmount, paidAmount,
    difference: Number((expectedAmount - paidAmount).toFixed(2)),
    status,
    riskFlags,
    requiresManualReview: riskFlags.length > 0 || status === 'OVERPAID'
  },
  processedAt: new Date().toISOString(),
  note: 'Starter reconciliation logic. Production duplicate detection requires checking paymentId against a persistent database or accounting system.'
}}];
